<?php
namespace App\Http\Controllers;
use App\Models\Workspace;
use App\Services\WorkspaceContext;
use App\Services\CrmAccess as Access;
use App\Services\TeamAccess;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class CrmController {
 public function __construct(private WorkspaceContext $context){}
 private function workspace(Request $r):Workspace{$w=$this->context->current($r);Access::role($w,$r->user());return $w;}
 private function q(Workspace $w,string $table){return Access::query($w,'crm_'.$table);}
 private function row(Workspace $w,string $table,int $id){$v=$this->q($w,$table)->where('id',$id)->first();abort_unless($v,404);return $v;}
 private function fail(string $key,string $message):never{throw ValidationException::withMessages([$key=>$message]);}
 private function today(Request $r):string{return now()->setTimezone($r->user()->timezone?:'UTC')->toDateString();}
 private function change(Request $r,callable $fn){$w=$this->workspace($r);DB::transaction(function()use($r,$w,$fn){Access::lock($w,$r->user());$fn($w);});return back()->with('status','CRM record saved.');}
 private function insert(Request $r,Workspace $w,string $table,array $data):int{$id=DB::table('crm_'.$table)->insertGetId($data+['workspace_id'=>$w->id,'created_at'=>now(),'updated_at'=>now()]);Access::audit($w,$r->user(),'crm_'.$table.'_created',$table,$id);return $id;}
 private function update(Request $r,Workspace $w,string $table,int $id,array $data):void{$this->row($w,$table,$id);$this->q($w,$table)->where('id',$id)->update($data+['updated_at'=>now()]);Access::audit($w,$r->user(),'crm_'.$table.'_updated',$table,$id);}
 private function version($row,array $data):void{if((int)$row->version!==(int)$data['version'])$this->fail('version','Record changed. Reload and try again.');}
 public function index(Request $r){
  $w=$this->workspace($r);$filters=$r->validate(['q'=>'nullable|string|max:100','segment'=>'nullable|string|max:80','source'=>'nullable|string|max:80','stage'=>'nullable|in:qualified,proposal,negotiation,won,lost']);$q=trim($filters['q']??'');$segment=$filters['segment']??'';$source=$filters['source']??'';$stage=$filters['stage']??'';
  $companies=$this->q($w,'companies')->when($q!=='',fn($b)=>$b->where('name','like','%'.$q.'%'))->when($segment!=='',fn($b)=>$b->where('segment',$segment))->latest('id')->paginate(20,['*'],'companies')->withQueryString();
  $contacts=$this->q($w,'contacts')->when($q!=='',fn($b)=>$b->where(fn($b)=>$b->where('name','like','%'.$q.'%')->orWhere('email','like','%'.$q.'%')))->when($segment!=='',fn($b)=>$b->where('segment',$segment))->latest('id')->paginate(20,['*'],'contacts')->withQueryString();
  $leads=$this->q($w,'leads')->when($q!=='',fn($b)=>$b->where('title','like','%'.$q.'%'))->when($source!=='',fn($b)=>$b->where('source',$source))->latest('id')->paginate(20,['*'],'leads')->withQueryString();
  $deals=$this->q($w,'deals')->when($q!=='',fn($b)=>$b->where('title','like','%'.$q.'%'))->when($stage!=='',fn($b)=>$b->where('stage',$stage))->latest('id')->paginate(50,['*'],'deals')->withQueryString();
  $followups=$this->q($w,'followups')->orderByRaw('CASE WHEN completed_at IS NULL THEN 0 ELSE 1 END')->orderBy('due_date')->paginate(20,['*'],'followups')->withQueryString();
  $documents=$this->q($w,'documents')->latest('id')->paginate(20,['*'],'documents')->withQueryString();$interactions=$this->q($w,'interactions')->latest('local_date')->latest('id')->paginate(20,['*'],'interactions')->withQueryString();$activity=$this->q($w,'activity')->latest('id')->paginate(20,['*'],'activity')->withQueryString();
  $companyChoices=$this->q($w,'companies')->orderBy('name')->get(['id','name']);$contactChoices=$this->q($w,'contacts')->orderBy('name')->get(['id','name']);$leadChoices=$this->q($w,'leads')->orderBy('title')->get(['id','title','status']);$dealChoices=$this->q($w,'deals')->orderBy('title')->get(['id','title','stage','currency']);$staff=$w->members()->get(['users.id','users.name'])->filter(fn($u)=>Access::canView($w,$u))->values();$names=$w->members()->pluck('users.name','users.id');$stats=Access::stats($w,$r->user());$today=$this->today($r);
  return view('crm.index',compact('companies','contacts','leads','deals','followups','documents','interactions','activity','companyChoices','contactChoices','leadChoices','dealChoices','staff','names','stats','today','q','segment','source','stage'));
 }
 public function company(Request $r,?int $id=null){$this->workspace($r);$d=$r->validate(['name'=>'required|string|max:200','website'=>'nullable|url:http,https|max:2048','industry'=>'nullable|string|max:120','segment'=>'nullable|string|max:80']);return $this->change($r,function($w)use($r,$id,$d){if($id)$this->update($r,$w,'companies',$id,$d);else $this->insert($r,$w,'companies',$d);});}
 public function contact(Request $r,?int $id=null){$this->workspace($r);$d=$r->validate(['name'=>'required|string|max:200','company_id'=>'nullable|integer|min:1','email'=>'nullable|email|max:254','phone'=>'nullable|string|max:60','position'=>'nullable|string|max:120','segment'=>'nullable|string|max:80','lifecycle'=>'required|in:prospect,customer,inactive']);return $this->change($r,function($w)use($r,$id,$d){if(!empty($d['company_id']))$this->row($w,'companies',$d['company_id']);if($id)$this->update($r,$w,'contacts',$id,$d);else $this->insert($r,$w,'contacts',$d);});}
 private function assignee(Workspace $w,int $id):void{$u=TeamAccess::target($w,$id);abort_unless(Access::canView($w,$u),422,'Assignee must have CRM access.');}
 public function lead(Request $r){$this->workspace($r);$d=$r->validate(['contact_id'=>'required|integer|min:1','assignee_id'=>'nullable|integer|min:1','title'=>'required|string|max:200','source'=>'required|string|max:80']);return $this->change($r,function($w)use($r,$d){$this->row($w,'contacts',$d['contact_id']);if(!empty($d['assignee_id']))$this->assignee($w,$d['assignee_id']);$this->insert($r,$w,'leads',$d+['status'=>'new']);});}
 public function updateLead(Request $r,int $id){$this->workspace($r);$d=$r->validate(['title'=>'required|string|max:200','source'=>'required|string|max:80','assignee_id'=>'nullable|integer|min:1','status'=>'required|in:new,contacted,qualified,lost','version'=>'required|integer|min:1']);return $this->change($r,function($w)use($r,$id,$d){$l=$this->row($w,'leads',$id);$this->version($l,$d);if($l->status==='converted')$this->fail('status','Converted leads are retained as history.');if(!empty($d['assignee_id']))$this->assignee($w,$d['assignee_id']);$d['version']=$l->version+1;$this->update($r,$w,'leads',$id,$d);});}
 public function deal(Request $r){$this->workspace($r);$d=$r->validate(['lead_id'=>'required|integer|min:1','title'=>'required|string|max:200','currency'=>'required|in:BDT,USD','amount'=>'required|numeric|decimal:0,2|min:0|max:999999999999.99','expected_close'=>'nullable|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:2100-12-31']);return $this->change($r,function($w)use($r,$d){$l=$this->row($w,'leads',$d['lead_id']);if($l->status!=='qualified'||$this->q($w,'deals')->where('lead_id',$l->id)->exists())$this->fail('lead_id','Only an unconverted qualified lead can create a deal.');$this->insert($r,$w,'deals',$d+['stage'=>'qualified']);$this->update($r,$w,'leads',$l->id,['status'=>'converted','version'=>$l->version+1]);});}
 public function updateDeal(Request $r,int $id){$this->workspace($r);$d=$r->validate(['title'=>'required|string|max:200','amount'=>'required|numeric|decimal:0,2|min:0|max:999999999999.99','expected_close'=>'nullable|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:2100-12-31','stage'=>'required|in:qualified,proposal,negotiation,won,lost','version'=>'required|integer|min:1']);return $this->change($r,function($w)use($r,$id,$d){$deal=$this->row($w,'deals',$id);$this->version($deal,$d);if(in_array($deal->stage,['won','lost'],true))$this->fail('stage','Closed deals are immutable.');$closed=in_array($d['stage'],['won','lost'],true);$this->update($r,$w,'deals',$id,array_merge($d,['closed_at'=>$closed?now():null,'version'=>$deal->version+1]));if($d['stage']==='won'){$lead=$this->row($w,'leads',$deal->lead_id);$this->update($r,$w,'contacts',$lead->contact_id,['lifecycle'=>'customer']);}});}
 public function followup(Request $r){$this->workspace($r);$d=$r->validate(['lead_id'=>'required|integer|min:1','user_id'=>'required|integer|min:1','title'=>'required|string|max:200','due_date'=>'required|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:2100-12-31']);return $this->change($r,function($w)use($r,$d){$this->row($w,'leads',$d['lead_id']);$this->assignee($w,$d['user_id']);$this->insert($r,$w,'followups',$d);});}
 public function completeFollowup(Request $r,int $id){$this->workspace($r);$d=$r->validate(['completed'=>'required|boolean']);return $this->change($r,function($w)use($r,$id,$d){$f=$this->row($w,'followups',$id);if((bool)$f->completed_at===(bool)$d['completed'])return;$this->update($r,$w,'followups',$id,['completed_at'=>$d['completed']?now():null]);});}
 public function document(Request $r){$this->workspace($r);$d=$r->validate(['deal_id'=>'required|integer|min:1','kind'=>'required|in:proposal,quotation','title'=>'required|string|max:200','body'=>'required|string|max:30000','amount'=>'required|numeric|decimal:0,2|min:0|max:999999999999.99','valid_until'=>'nullable|date_format:Y-m-d|after_or_equal:'.$this->today($r).'|before_or_equal:2100-12-31']);return $this->change($r,function($w)use($r,$d){$deal=$this->row($w,'deals',$d['deal_id']);if(in_array($deal->stage,['won','lost'],true))$this->fail('deal_id','Deal is closed.');$this->insert($r,$w,'documents',$d+['currency'=>$deal->currency,'user_id'=>$r->user()->id,'status'=>'draft']);});}
 public function documentStatus(Request $r,int $id){$this->workspace($r);$d=$r->validate(['status'=>'required|in:sent,accepted,rejected,void','version'=>'required|integer|min:1']);return $this->change($r,function($w)use($r,$id,$d){$doc=$this->row($w,'documents',$id);$this->version($doc,$d);$allowed=['draft'=>['sent','void'],'sent'=>['accepted','rejected','void']];if(!in_array($d['status'],$allowed[$doc->status]??[],true))$this->fail('status','Invalid document transition.');if(in_array($d['status'],['sent','accepted'],true)&&$doc->valid_until&&$doc->valid_until<$this->today($r))$this->fail('status','Document expired.');$this->update($r,$w,'documents',$id,['status'=>$d['status'],'version'=>$doc->version+1]);});}
 public function printDocument(Request $r,int $id){$w=$this->workspace($r);$doc=$this->row($w,'documents',$id);$deal=$this->row($w,'deals',$doc->deal_id);$lead=$this->row($w,'leads',$deal->lead_id);$contact=$this->row($w,'contacts',$lead->contact_id);return view('crm.document',compact('w','doc','deal','contact'));}
 public function interaction(Request $r){$this->workspace($r);$d=$r->validate(['contact_id'=>'required|integer|min:1','channel'=>'required|in:note,email,phone,meeting,whatsapp,other','local_date'=>'required|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:'.$this->today($r),'body'=>'required|string|max:10000']);return $this->change($r,function($w)use($r,$d){$this->row($w,'contacts',$d['contact_id']);$this->insert($r,$w,'interactions',$d+['user_id'=>$r->user()->id]);});}
}
